Note that there is a similar situation which can also happen during
`probe()`; the possibility of an interrupt firing _before_ registering
the `power_supply` handle. This would then lead to the nasty situation
of using the `power_supply` handle *uninitialized* in
`power_supply_changed()`.

Commit 1c1f13a006ed ("power: supply: ab8500: Move to componentized
binding") introduced this issue during a refactorization. Fix this racy
use-after-free by making sure the IRQ is requested _after_ the
registration of the `power_supply` handle.

Fixes: 1c1f13a006ed ("power: supply: ab8500: Move to componentized binding")
Signed-off-by: Waqar Hameed <waqar.hameed@axis.com>
Reviewed-by: Linus Walleij <linusw@kernel.org>
Link: https://patch.msgid.link/ccf83a09942cb8dda3dff70b2682f2c2e9cb97f2.1766268280.git.waqar.hameed@axis.com
Signed-off-by: Sebastian Reichel <sebastian.reichel@collabora.com>

Here is the root cause:
The interrupt handlers were requested using `devm_request_threaded_irq` before the `power_supply` handle was allocated and registered. Since `devm_` resources are freed in reverse order, the `power_supply` gets freed before the interrupt handler is unregistered during removal. This creates a race where a late interrupt can call `power_supply_changed()` with a freed `power_supply` pointer, causing use-after-free. Additionally, during probe, an interrupt could fire before the `power_supply` is registered, leading to the use of an uninitialized pointer.

Here is the patch:

 static int ab8500_charger_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct device_node *np = dev->of_node;
 	struct component_match *match = NULL;
 	struct power_supply_config ac_psy_cfg = {}, usb_psy_cfg = {};
 	struct ab8500_charger *di;
 	int charger_status;
 	int i, irq;
 	int ret;

 	di = devm_kzalloc(dev, sizeof(*di), GFP_KERNEL);
 	if (!di)
 		return -ENOMEM;

 	di->bm = &ab8500_bm_data;

 	di->autopower_cfg = of_property_read_bool(np, "autopower_cfg");

 	/* get parent data */
 	di->dev = dev;
 	di->parent = dev_get_drvdata(pdev->dev.parent);

 	/* Get ADC channels */
 	if (!is_ab8505(di->parent)) {
 		di->adc_main_charger_v = devm_iio_channel_get(dev, "main_charger_v");
 		if (IS_ERR(di->adc_main_charger_v)) {
 			ret = dev_err_probe(dev, PTR_ERR(di->adc_main_charger_v),
 					    "failed to get ADC main charger voltage\n");
 			return ret;
 		}
 		di->adc_main_charger_c = devm_iio_channel_get(dev, "main_charger_c");
 		if (IS_ERR(di->adc_main_charger_c)) {
 			ret = dev_err_probe(dev, PTR_ERR(di->adc_main_charger_c),
 					    "failed to get ADC main charger current\n");
 			return ret;
 		}
 	}
 	di->adc_vbus_v = devm_iio_channel_get(dev, "vbus_v");
 	if (IS_ERR(di->adc_vbus_v)) {
 		ret = dev_err_probe(dev, PTR_ERR(di->adc_vbus_v),
 				    "failed to get ADC USB charger voltage\n");
 		return ret;
 	}
 	di->adc_usb_charger_c = devm_iio_channel_get(dev, "usb_charger_c");
 	if (IS_ERR(di->adc_usb_charger_c)) {
 		ret = dev_err_probe(dev, PTR_ERR(di->adc_usb_charger_c),
 				    "failed to get ADC USB charger current\n");
 		return ret;
 	}

 	/*
 	 * VDD ADC supply needs to be enabled from this driver when there
 	 * is a charger connected to avoid erroneous BTEMP_HIGH/LOW
 	 * interrupts during charging
 	 */
 	di->regu = devm_regulator_get(dev, "vddadc");
 	if (IS_ERR(di->regu)) {
 		ret = PTR_ERR(di->regu);
 		dev_err(dev, "failed to get vddadc regulator\n");
 		return ret;
 	}

